class Parent {
    protected int a = 5;
    protected int b;
    protected void inc() { a = a + 1; b = b + 1; }
    public Parent(int x) { b = x; inc(); }
}
class Child extends Parent {
    @Override
    protected void inc() { a = a + 2; b = b + 2; }
    public Child() { super(33); }
}
Child y = new Child();
